contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient, uint256 amount) public {
        require(c.owner() == address(this));
        require(recipient == address(this));
        require(amount > 0);
        require(address(this).balance >= amount);

        // fund c through its payable fallback (top-level state-changing call)
        (bool ok, ) = address(c).call{value: amount}("");
        require(ok);

        // owner withdraws everything to recipient
        c.withdrawAll(recipient);

        // P: transfer either succeeds fully or reverts, so balance is always 0.
        // M: send may fail silently, leaving a nonzero balance.
        assert(address(c).balance == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address recipient) public {
        // This test contract is NOT the owner of c (owner was set at deployment to another address),
        // so any withdrawAll attempt from here must fail without moving funds.
        uint256 balBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: a non-owner's withdrawal attempt reverts, and the contract's
        // balance is untouched (no transfer may be observable to the recipient).
        assert(reverted && address(c).balance == balBefore);
    }

    receive() external payable {}
    fallback() external payable {}
}

